	candidate := base
	if _, err := os.Lstat(filepath.Join(root, candidate)); os.IsNotExist(err) {
		return candidate
	}
	candidate = base + "-" + suffix
	if _, err := os.Lstat(filepath.Join(root, candidate)); os.IsNotExist(err) {
		return candidate
	}
	for i := 1; ; i++ {
