  3181	func buildBrainRetrievalStatus(ctx context.Context, runner CommandRunner, repoDir string, manifest *exportManifest, live brainLiveState) *brainStatusRetrieval {
  3182		report := &brainStatusRetrieval{}
  3183		axes := map[string]staleAxis{}
  3184		if manifest == nil || manifest.Sources == nil || manifest.Sources.Seed == nil {
  3185			axes["seed"] = staleAxis{State: "missing", Detail: "no seed source in manifest; run entire brain refresh --agent none"}
  3186		} else {
  3187			seed := manifest.Sources.Seed
  3188			report.SeedCommit = seed.Commit
  3189			report.SeedMode = seed.WorktreeMode
  3190			switch {
  3191			case live.Head == "":
  3192				axes["seed"] = staleAxis{State: "unsafe", Detail: "current HEAD unavailable", Indexed: seed.Commit}
  3193			case seed.Commit != live.Head:
  3194				axes["seed"] = staleAxis{State: "stale", Detail: "seed and docs are based on an older commit; run entire brain refresh --agent none", Current: live.Head, Indexed: seed.Commit}
  3195			case seed.WorktreeMode != "worktree" && live.Dirty:
  3196				axes["seed"] = staleAxis{State: "dirty-unindexed", Detail: "seed and docs are based on committed HEAD; refresh with --worktree to include current changes", Current: live.Head, Indexed: seed.Commit}
  3197			case seed.WorktreeMode != "worktree":
  3198				axes["seed"] = staleAxis{State: "ok", Detail: "seed and docs match committed HEAD", Current: live.Head, Indexed: seed.Commit}
  3199			case seed.WorktreeHash == "":
  3200				axes["seed"] = staleAxis{State: "unsafe", Detail: "worktree seed snapshot has no verifiable fingerprint; refresh again with --worktree", Current: live.Head, Indexed: seed.Commit}
  3201			case !live.Dirty:
  3202				axes["seed"] = staleAxis{State: "worktree-overlay-stale", Detail: "seed was built from dirty content but the worktree is now clean", Current: live.Head, Indexed: seed.Commit}
  3203			default:
  3204				currentHash, err := worktreeFingerprint(ctx, runner, repoDir)
  3205				if err != nil {
  3206					axes["seed"] = staleAxis{State: "unsafe", Detail: "worktree fingerprint unavailable: " + err.Error(), Current: live.Head, Indexed: seed.Commit}
  3207				} else if currentHash != seed.WorktreeHash {
  3208					axes["seed"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since seed and docs refresh", Current: currentHash, Indexed: seed.WorktreeHash}
  3209				} else {
  3210					axes["seed"] = staleAxis{State: "dirty-indexed", Detail: "seed and docs include the current dirty worktree", Current: currentHash, Indexed: seed.WorktreeHash}
  3211				}
  3212			}
  3213		}
  3214		if manifest == nil || manifest.Sources == nil || manifest.Sources.Docs == nil {
  3215			axes["docs"] = staleAxis{State: "missing", Detail: "no docs index in manifest; run entire brain refresh --agent none"}
  3216		} else {
  3217			docs := manifest.Sources.Docs
  3218			report.DocsGeneratedAt = docs.GeneratedAt.Format(time.RFC3339)
  3219			report.DocsRecords = docs.Records
  3220			report.DocsFiles = docs.Files
  3221			if docs.GeneratedAt.IsZero() {
  3222				axes["docs"] = staleAxis{State: "unsafe", Detail: "docs index has no generation timestamp"}
  3223			} else if manifest.Sources.Seed == nil {
  3224				axes["docs"] = staleAxis{State: "unsafe", Detail: "docs index provenance cannot be checked without a seed source"}
  3225			} else if docs.GeneratedAt.Before(manifest.Sources.Seed.GeneratedAt) {
  3226				axes["docs"] = staleAxis{State: "stale", Detail: "docs index predates the current seed; run entire brain refresh --agent none", Current: manifest.Sources.Seed.GeneratedAt.Format(time.RFC3339), Indexed: docs.GeneratedAt.Format(time.RFC3339)}
  3227			} else {
  3228				axes["docs"] = staleAxis{State: "ok", Detail: "docs index was built from the current seed"}
  3229			}
  3230		}
  3231		report.Freshness = &staleReport{Severity: aggregateStaleSeverity(axes), Axes: axes}
  3232		return report
  3233	}
