    83	// surface names the read surface for serve receipts ("search"/"vsearch"/
    84	// "query" from the CLI, "mcp:brain_*" from the MCP server).
    85	func runRetrieve(ctx context.Context, cmd *cobra.Command, opts Options, query string, mode retrievalMode, limit int, branch string, jsonOut, patterns bool, surface string) error {
    86		// Reject --limit <= 0 rather than silently defaulting, so a typo like
    87		// `--limit 0` is an explicit error (matching the rest of the CLI surface). The
    88		// MCP path passes a validated positive limit, so it's unaffected.
    89		if limit <= 0 {
    90			return fmt.Errorf("--limit must be greater than 0")
    91		}
    92		repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
    93		if err != nil {
    94			return err
    95		}
    96		results, err := retrieveUnified(repoDir, brainDir, resolvedBranch, query, limit, mode)
    97		if err != nil {
    98			return err
    99		}
   100		factIDs := unifiedFactIDs(results)
   101		recordReceipt := func() {
   102			recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, surface,
   103				vitalityHead(ctx, opts.Runner, repoDir), query, factIDs)
   104		}
   105		// Discoverability only: pattern/theme pointers never enter the facts/history/
   106		// docs ranking — they are a separate, capped, opt-in section so default
   107		// retrieval quality is unchanged by construction.
   108		var related []relatedPatternRef
   109		if patterns {
   110			related = relatedPatternPointers(brainDir, query, patternPointerCap)
   111		}
   112		if jsonOut {
   113			// Preserve the established JSON `text` field on both CLI and MCP
   114			// surfaces. Excerpt is additive; existing consumers must not be forced to
   115			// switch to a second brain_get round trip.
   116			out := map[string]any{"query": query, "branch": resolvedBranch, "results": compactUnifiedResults(results, query)}
   117			hints := retrievalHintsForResults(repoDir, results, query)
   118			if len(hints.LikelyEditFiles) > 0 {
   119				out["likely_edit_files"] = hints.LikelyEditFiles
   120			}
   121			if len(hints.LikelyTestFiles) > 0 {
   122				out["likely_test_files"] = hints.LikelyTestFiles
   123			}
   124			if len(hints.ActionChecklist) > 0 {
   125				out["action_checklist"] = hints.ActionChecklist
   126			}
   127			if len(related) > 0 {
   128				out["related_patterns"] = related
   129			}
   130			if len(results) == 0 {
   131				if note := emptyResultBlindSpot(brainDir); note != "" {
   132					out["blind_spot"] = note
   133				}
   134			}
   135			if err := writeJSON(cmd, out); err != nil {
   136				return err
   137			}
   138			if len(factIDs) > 0 {
   139				recordReceipt()
   140			}
   141			return nil
   142		}
   143		if err := writeText(cmd, func(out io.Writer) {
   144			if len(results) == 0 {
   145				fmt.Fprintf(out, "no results for %q\n", query)
   146				if note := emptyResultBlindSpot(brainDir); note != "" {
   147					fmt.Fprintln(out, note)
   148				}
   149				// still show related pattern pointers if any
   150			}
   151			hints := retrievalHintsForResults(repoDir, results, query)
   152			for _, file := range hints.LikelyEditFiles {
   153				fmt.Fprintf(out, "edit_file %s\n", file)
   154			}
   155			for _, file := range hints.LikelyTestFiles {
   156				fmt.Fprintf(out, "test_file %s\n", file)
   157			}
   158			for _, action := range hints.ActionChecklist {
   159				fmt.Fprintf(out, "action %s %s: %s\n", action.File, action.Symbol, action.Action)
   160			}
   161			for _, r := range results {
   162				ex := truncateString(strings.Join(strings.Fields(r.Text), " "), 200)
   163				loc := r.Path
   164				if r.Line > 0 {
   165					loc = fmt.Sprintf("%s:%d", r.Path, r.Line)
   166				}
   167				label := r.Source
   168				if r.VerificationRequired {
   169					label += " verify"
   170				}
   171				fmt.Fprintf(out, "[%s] %s  %s\n    %s\n", label, r.ID, loc, ex)
   172				printRetrievalCaveats(out, r)
   173			}
   174			for _, p := range related {
   175				fmt.Fprintf(out, "related [%s] %s  %s\n", p.Type, p.ID, p.Title)
   176			}
   177		}); err != nil {
   178			return err
   179		}
   180		if len(factIDs) > 0 {
   181			recordReceipt()
   182		}
   183		return nil
   184	}
