   186	func retrievalHintsForResults(repoRoot string, results []unifiedResult, query string) retrievalTaskHints {
   187		_ = query
   188		seen := map[string]struct{}{}
   189		var editFiles, testFiles []string
   190		addPath := func(path string) {
   191			clean, ok := cleanBrainBriefHistoryFile(repoRoot, path)
   192			if !ok || !brainBriefRepoFileExists(repoRoot, clean) {
   193				return
   194			}
   195			if _, ok := seen[clean]; ok {
   196				return
   197			}
   198			seen[clean] = struct{}{}
   199			if brainBriefLikelyTestFile(clean) {
   200				testFiles = append(testFiles, clean)
   201			} else {
   202				editFiles = append(editFiles, clean)
   203			}
   204		}
   205		for _, result := range results {
   206			if result.Source != "history" && result.Source != "doc" {
   207				continue
   208			}
   209			addPath(result.Path)
   210			for _, path := range extractBrainBriefPaths(result.Text) {
   211				addPath(path)
   212			}
   213		}
   214	
   215		// Pair an indexed test locator with its conventional implementation path.
   216		// This uses only the paths contained in indexed results plus bounded stat
   217		// calls; ordinary retrieval never scans or reads the live source tree.
   218		var siblingImplementations []string
   219		for _, testFile := range testFiles {
   220			for _, candidate := range retrievalSiblingImplementationCandidates(testFile) {
   221				if _, exists := seen[candidate]; exists || !brainBriefRepoFileExists(repoRoot, candidate) {
   222					continue
   223				}
   224				seen[candidate] = struct{}{}
   225				siblingImplementations = append(siblingImplementations, candidate)
   226			}
   227		}
   228		editFiles = append(siblingImplementations, editFiles...)
   229		if len(editFiles) > 3 {
   230			editFiles = editFiles[:3]
   231		}
   232		if len(testFiles) > 3 {
   233			testFiles = testFiles[:3]
   234		}
   235		return retrievalTaskHints{LikelyEditFiles: editFiles, LikelyTestFiles: testFiles}
   236	}
