   176	// handleMCPMessage dispatches a single request. It recovers from any panic in a
   177	// handler so that one malformed input (e.g. a crafted transcript or snapshot that
   178	// trips an unhandled edge case deep in processing) returns a JSON-RPC internal
   179	// error rather than tearing down the long-lived stdio server and every other
   180	// in-flight request.
   181	func handleMCPMessage(ctx context.Context, opts Options, msg mcpMessage) (response mcpMessage) {
   182		defer func() {
   183			if r := recover(); r != nil {
   184				response = mcpMessage{
   185					JSONRPC: "2.0",
   186					ID:      msg.ID,
