374	// dedupSeedCommands removes exact (Name, Command) duplicates — common in a
375	// monorepo where several package.json files surface the same scripted command —
376	// while preserving order. Same-name/different-command entries are kept (they are
377	// genuinely distinct) and disambiguated by source at render time.
378	func dedupSeedCommands(commands []seedCommand) []seedCommand {
379		if len(commands) == 0 {
380			return commands
381		}
382		seen := make(map[string]struct{}, len(commands))
383		out := make([]seedCommand, 0, len(commands))
384		for _, c := range commands {
385			key := c.Name + "\x00" + c.Command
386			if _, ok := seen[key]; ok {
387				continue
388			}
389			seen[key] = struct{}{}
390			out = append(out, c)
391		}
392		return out
393	}
