	if err != nil {
		t.Fatal(err)
	}
	defer reader.Close()
	reader.SetMaxOpenConns(1)

	var count int
	if err := reader.QueryRow(`SELECT COUNT(*) FROM runtime_traces`).Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Fatalf("initial runtime trace count = %d, want 0", count)
	}

	if _, err := writer.Exec(`INSERT INTO runtime_traces(imported_at, source_path, from_id, to_id, observed_type, matched_static_edge) VALUES (?, ?, ?, ?, ?, ?)`,
		"2026-08-06T00:00:00Z", "trace.ndjson", "caller", "callee", "CALLS", 1); err != nil {
		t.Fatal(err)
	}
	if err := reader.QueryRow(`SELECT COUNT(*) FROM runtime_traces`).Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 1 {
		t.Fatalf("runtime trace count after concurrent write = %d, want 1", count)
	}
}

