  1290	func semanticAvailableGenerationID(root, base, suffix string) string {
  1291		candidate := base
  1292		if _, err := os.Lstat(filepath.Join(root, candidate)); os.IsNotExist(err) {
  1293			return candidate
  1294		}
  1295		candidate = base + "-" + suffix
  1296		if _, err := os.Lstat(filepath.Join(root, candidate)); os.IsNotExist(err) {
  1297			return candidate
  1298		}
  1299		for i := 1; ; i++ {
  1300			candidate = fmt.Sprintf("%s-%s-%d", base, suffix, i)
  1301			if _, err := os.Lstat(filepath.Join(root, candidate)); os.IsNotExist(err) {
  1302				return candidate
  1303			}
  1304		}
  1305	}
