  1510	func semanticFileContentHash(repoDir, path string) string {
  1511		if path == "" {
  1512			return ""
  1513		}
  1514		clean, err := validateSemanticProviderPath(path)
  1515		if err != nil {
  1516			return ""
  1517		}
  1518		if err := rejectSymlinkPathComponents(repoDir, filepath.FromSlash(clean)); err != nil {
  1519			return ""
  1520		}
  1521		f, err := os.Open(filepath.Join(repoDir, filepath.FromSlash(clean)))
  1522		if err != nil {
  1523			return ""
  1524		}
  1525		defer f.Close()
  1526		hasher := sha256.New()
  1527		limited := io.LimitReader(f, semanticParseCacheMaxFile+1)
  1528		n, err := io.Copy(hasher, limited)
  1529		if err != nil || n > semanticParseCacheMaxFile {
  1530			return ""
  1531		}
  1532		sum := hasher.Sum(nil)
  1533		return "sha256:" + hex.EncodeToString(sum[:])
  1534	}
