  1536	func writeSemanticParseCacheArtifact(generationDir, path, blob, contentHash string) (string, error) {
  1537		key := contentHash
  1538		if key == "" {
  1539			sum := sha256.Sum256([]byte(path + "\x00" + blob))
  1540			key = "sha256:" + hex.EncodeToString(sum[:])
  1541		}
  1542		if !strings.HasPrefix(key, "sha256:") {
  1543			sum := sha256.Sum256([]byte(path + "\x00" + blob + "\x00" + key))
  1544			key = "sha256:" + hex.EncodeToString(sum[:])
  1545		}
  1546		cleanKey := strings.TrimPrefix(key, "sha256:")
  1547		if len(cleanKey) < 4 {
  1548			cleanKey = hex.EncodeToString([]byte(cleanKey))
  1549		}
  1550		rel := filepath.Join("parse-cache", cleanKey[:2], cleanKey[2:4], cleanKey+".json")
  1551		payload := map[string]string{
  1552			"path":         path,
  1553			"blob":         blob,
  1554			"content_hash": key,
  1555		}
  1556		data, err := json.MarshalIndent(payload, "", "  ")
  1557		if err != nil {
  1558			return "", err
  1559		}
  1560		data = append(data, '\n')
  1561		if err := writeFileAtomic(filepath.Join(generationDir, rel), data, 0o600); err != nil {
  1562			return "", err
  1563		}
  1564		return filepath.ToSlash(rel), nil
