 13		"github.com/spf13/cobra"
 14	)
 15	
 16	const (
 17		// factsBackendLocalGitmeta is the default: a bare, on-disk git-meta store
 18		// under the plugin cache — fully local, no network/entiredb/Postgres.
 19		factsBackendLocalGitmeta = "local-gitmeta"
 20		// factsBackendHTTP drives the hosted entire-api FactSetStore (factsync.HTTPServer).
 21		factsBackendHTTP = "http"
 22		// envFactsBackend selects the backend when --facts-backend is unset.
 23		envFactsBackend = "ENTIRE_BRAIN_FACTS_BACKEND"
 24	)
 25	
 26	// factsSyncOptions bundles the flag state for `facts sync`.
 27	type factsSyncOptions struct {
 28		branch  string
 29		backend string
 30		member  string
 31		// http backend only (mirror publish's flag/env resolution):
 32		apiURL string
 33		token  string
 34		repoID string
 35	
 36		jsonOut bool
 37	}
 38	
 39	func newFactsSyncCommand(opts Options) *cobra.Command {
 40		var syncOpts factsSyncOptions
 41		cmd := &cobra.Command{
 42			Use:   "sync",
 43			Short: "Read-merge-CAS this branch's local facts into the shared fact-set head",
 44			Long: `sync runs the factsync read-merge-CAS loop for the current branch: pull the
 45	current fact-set head, keep-both merge this member's local facts into it, and
 46	compare-and-swap the result back — retrying on a losing swap.
 47	
 48	Backends (--facts-backend, or ` + envFactsBackend + `):
 49	  local-gitmeta  (default) a bare, on-disk git-meta store under the brain cache
 50	                 (<cache>/brain/<repo-key>/gitmeta.git); fully local, no network,
 51	                 entiredb, or Postgres.
 52	  http           the hosted entire-api FactSetStore; opt-in, requires
 53	                 --api-url/ENTIRE_API_URL, --repo-id/ENTIRE_REPO_ID,
 54	                 --token/ENTIRE_API_TOKEN and ENTIRE_BRAIN_ALLOW_HOSTED=1.`,
 55			Args: cobra.NoArgs,
 56			RunE: func(cmd *cobra.Command, args []string) error {
 57				return runFactsSync(cmd, opts, syncOpts)
 58			},
 59		}
 60		cmd.Flags().StringVar(&syncOpts.branch, "branch", "", "Branch to sync (default: current branch)")
 61		cmd.Flags().StringVar(&syncOpts.backend, "facts-backend", "", "Fact-set backend: local-gitmeta (default) or http")
 62		cmd.Flags().StringVar(&syncOpts.member, "member", "", "Member identity stamped on cross-member proposals (default: git user.email)")
 63		cmd.Flags().StringVar(&syncOpts.repoID, "repo-id", "", "Target repo id for the http backend (overrides ENTIRE_REPO_ID)")
 64		cmd.Flags().StringVar(&syncOpts.apiURL, "api-url", "", "Entire API base URL for the http backend (overrides ENTIRE_API_URL)")
 65		cmd.Flags().StringVar(&syncOpts.token, "token", "", "Entire API bearer token for the http backend (overrides ENTIRE_API_TOKEN)")
 66		cmd.Flags().BoolVar(&syncOpts.jsonOut, "json", false, "Emit the sync result as JSON")
 67		return cmd
 68	}
 69	
 70	func runFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions) error {
 71		ctx := cmd.Context()
 72	
 73		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
 74		if err != nil {
 75			return err
 76		}
 77		if !local {
 78			return fmt.Errorf("facts sync requires a local repository path")
 79		}
 80		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
 81		if err != nil {
 82			return err
 83		}
 84	
 85		branch := strings.TrimSpace(syncOpts.branch)
 86		if branch == "" {
 87			if current, gitErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
 88				branch = strings.TrimSpace(current)
 89			}
 90		}
 91		if branch == "" {
 92			branch = distillDefaultBranch
 93		}
 94	
 95		facts, err := loadFacts(storage.BrainDir, branch)
 96		if err != nil {
 97			return err
 98		}
 99		memberID := resolveSyncMemberID(ctx, opts.Runner, repoDir, syncOpts.member)
100	
101		srv, repoID, backendLabel, err := buildFactsSyncBackend(opts, resolveFactsBackendName(syncOpts.backend), storage, syncOpts)
102		if err != nil {
103			return err
104		}
105	
106		// The merge runs on this runner (ADR-P1-E); the backend only stores the blob
107		// and CAS-swaps the head. Sync retries on a losing swap and never drops a
108		// member's fact.
109		res, err := factsync.Sync(ctx, srv, repoID, branch, memberID, facts, opts.Now().UTC())
110		if err != nil {
111			return err
112		}
113	
114		if syncOpts.jsonOut {
115			return writeJSON(cmd, map[string]any{
116				"branch":    branch,
117				"backend":   backendLabel,
118				"member":    memberID,
119				"published": res.Published,
120				"ref":       res.NewRef,
121				"attempts":  res.Attempts,
122				"proposals": res.Proposals,
123				"facts":     len(facts),
124			})
125		}
126	
127		out := cmd.OutOrStdout()
128		if res.Published {
129			fmt.Fprintf(out, "synced %d local fact(s) on %s via %s: head advanced to %s (%d attempt(s))\n",
130				len(facts), branch, backendLabel, res.NewRef, res.Attempts)
131		} else {
132			fmt.Fprintf(out, "synced %d local fact(s) on %s via %s: no change; head at %s (%d attempt(s))\n",
133				len(facts), branch, backendLabel, refOrNone(res.NewRef), res.Attempts)
134		}
135		if len(res.Proposals) > 0 {
136			fmt.Fprintf(out, "%d cross-member conflict(s) queued for review:\n", len(res.Proposals))
137			for _, p := range res.Proposals {
138				fmt.Fprintf(out, "  %s %s -> %s (by %s, confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.ProposedBy, p.Confidence)
139			}
140		}
141		return nil
142	}
