package factsync

import "github.com/ashtom/entire-brain/internal/factmerge"

// SanitizeForEgress redacts a fact's LOCAL-ONLY provenance coordinates before its
// facts leave this member for the shared, cross-member head. A provenance Anchor mixes
// two kinds of data:
//
//   - cross-member-meaningful, opaque ids another member can carry but never resolve
//     against its own machine: SessionID, Commit, CheckpointID, TurnID, Verified;
//   - LOCAL filesystem coordinates that are meaningless to — and would leak this
//     member's directory layout at — any other member: Transcript (a brain-relative
//     path on THIS machine) and Line (an offset into that local file).
//
// The reasoning layer treats the local coordinates as OPAQUE and never resolves a peer's
// anchor (ADR-P1: local-only anchors stay opaque cross-member). SanitizeForEgress makes
// that guarantee structural: it clears Transcript+Line on every anchor so the synced
// blob carries no member's local path, while keeping the opaque ids so provenance still
// unions correctly (UnionAnchors dedups by value; a shared fact from two members keeps
// both members' SessionIDs). Fact identity is unaffected — RecordID derives from text +
// paths only, never provenance.
//
// It returns a deep copy; the caller's in-memory local facts (which the member still
// wants full local provenance for) are never mutated.
func SanitizeForEgress(records []factmerge.Record) []factmerge.Record {
	if records == nil {
		return nil
	}
	out := make([]factmerge.Record, len(records))
	for i, r := range records {
		r.Provenance = sanitizeAnchors(r.Provenance)
		out[i] = r
	}
	return out
}

func sanitizeAnchors(anchors []factmerge.Anchor) []factmerge.Anchor {
	if anchors == nil {
		return nil
	}
	out := make([]factmerge.Anchor, len(anchors))
	for i, a := range anchors {
		// Drop the local filesystem coordinates; keep the opaque cross-member ids.
		a.Transcript = ""
		a.Line = 0
		out[i] = a
	}
	return out
}
package factsync

import (
	"bytes"
	"context"
	"strings"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// anchoredFact builds a fact whose single provenance anchor carries BOTH opaque
// cross-member ids (session, commit, checkpoint) and LOCAL filesystem coordinates
// (transcript path + line) — the shape SanitizeForEgress must split.
func anchoredFact(text string, paths []string, a factmerge.Anchor, now time.Time) factmerge.Record {
	np := factmerge.NormalizePaths(paths)
	return factmerge.Record{
		ID:         factmerge.RecordID(text, np),
		Paths:      np,
		Text:       text,
		Branch:     "main",
		Origin:     "distilled",
		Status:     factmerge.StatusActive,
		Provenance: []factmerge.Anchor{a},
		CreatedAt:  now,
		UpdatedAt:  now,
	}
}

// TestSyncStripsLocalPathsButKeepsOpaqueProvenance proves the no-leak guarantee: a fact
// synced cross-member arrives with its local transcript path + line REDACTED, while the
// opaque cross-member ids (session, commit, checkpoint) survive — and the serialized
// blob on the shared head contains no trace of the member's local filesystem layout.
func TestSyncStripsLocalPathsButKeepsOpaqueProvenance(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	const localPath = "sessions/2026-07-07/Users-thomi-secret/transcript.jsonl"
	local := []factmerge.Record{anchoredFact(
		"ci runs on self-hosted runners", []string{"ci.runner.host"},
		factmerge.Anchor{SessionID: "sess-1", Commit: "deadbeef", CheckpointID: "ckpt-9", Transcript: localPath, Line: 42},
		now,
	)}

	if _, err := Sync(ctx, srv, "repo", "main", "member-A", local, now); err != nil {
		t.Fatalf("sync: %v", err)
	}

	// The caller's own local slice must be untouched (still has the path locally).
	if local[0].Provenance[0].Transcript != localPath {
		t.Fatalf("SanitizeForEgress mutated the caller's local facts: %q", local[0].Provenance[0].Transcript)
	}

	// The shared head must carry the fact WITHOUT the local path/line, WITH the opaque ids.
	_, blob, found, err := srv.Current(ctx, "repo", "main")
	if err != nil || !found {
		t.Fatalf("Current: found=%v err=%v", found, err)
	}
	if bytes.Contains(blob, []byte("Users-thomi")) || strings.Contains(string(blob), localPath) {
		t.Fatalf("LOCAL PATH LEAKED into the shared head blob:\n%s", blob)
	}
	recs, err := factmerge.ParseNDJSON(bytes.NewReader(blob))
	if err != nil {
		t.Fatalf("parse head: %v", err)
	}
	if len(recs) != 1 || len(recs[0].Provenance) != 1 {
		t.Fatalf("head = %d recs; want 1 with 1 anchor", len(recs))
	}
	a := recs[0].Provenance[0]
	if a.Transcript != "" || a.Line != 0 {
		t.Fatalf("local coords not redacted: transcript=%q line=%d", a.Transcript, a.Line)
	}
	if a.SessionID != "sess-1" || a.Commit != "deadbeef" || a.CheckpointID != "ckpt-9" {
		t.Fatalf("opaque cross-member ids not preserved: %+v", a)
	}
}

// TestSyncEmptyMergeConverges proves the empty-merge guard: a member with NO active
// local facts syncing into an EMPTY head produces an empty merged set, which must be
// reported as converged (nothing to publish) rather than pushed as an empty blob — the
// real server rejects empty plaintext (400), and the fake now mirrors that reject, so a
// missing guard would surface as an error here.
func TestSyncEmptyMergeConverges(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	// A retracted (non-active) local fact: Promote skips it, so the merged set is empty.
	f := fact("stale retracted fact", []string{"x.y.z"}, "s", now)
	f.Status = factmerge.StatusRetracted

	res, err := Sync(ctx, srv, "repo", "main", "member-A", []factmerge.Record{f}, now)
	if err != nil {
		t.Fatalf("empty-merge sync errored (guard missing?): %v", err)
	}
	if res.Published {
		t.Fatalf("empty merge reported Published=true; want converged/no publish")
	}
	// Head must remain empty — nothing was pushed.
	if _, _, found, _ := srv.Current(ctx, "repo", "main"); found {
		t.Fatal("empty merge pushed a blob to the head; want head untouched")
	}
}

// TestSyncUnionsProvenanceAfterSanitize proves sanitization does not break provenance
// union: two members learn the SAME fact (same text+paths → same id) with DIFFERENT
// local transcripts and DIFFERENT sessions. After both sync, the shared fact carries the
// UNION of both sessions, and NEITHER member's local path is present.
func TestSyncUnionsProvenanceAfterSanitize(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	text, paths := "the primary db is postgres", []string{"data.store.engine"}
	a := []factmerge.Record{anchoredFact(text, paths,
		factmerge.Anchor{SessionID: "sess-A", Transcript: "sessions/A/local-A.jsonl", Line: 1}, now)}
	b := []factmerge.Record{anchoredFact(text, paths,
		factmerge.Anchor{SessionID: "sess-B", Transcript: "sessions/B/local-B.jsonl", Line: 2}, now)}

	if _, err := Sync(ctx, srv, "repo", "main", "member-A", a, now); err != nil {
		t.Fatal(err)
	}
	if _, err := Sync(ctx, srv, "repo", "main", "member-B", b, now); err != nil {
		t.Fatal(err)
	}

	_, blob, _, _ := srv.Current(ctx, "repo", "main")
	if bytes.Contains(blob, []byte("local-A.jsonl")) || bytes.Contains(blob, []byte("local-B.jsonl")) {
		t.Fatalf("a member local path leaked:\n%s", blob)
	}
	recs, err := factmerge.ParseNDJSON(bytes.NewReader(blob))
	if err != nil {
		t.Fatal(err)
	}
	if len(recs) != 1 {
		t.Fatalf("head = %d recs; want 1 (shared fact deduped)", len(recs))
	}
	sessions := map[string]bool{}
	for _, an := range recs[0].Provenance {
		if an.Transcript != "" {
			t.Fatalf("unsanitized anchor in union: %+v", an)
		}
		sessions[an.SessionID] = true
	}
	if !sessions["sess-A"] || !sessions["sess-B"] || len(recs[0].Provenance) != 2 {
		t.Fatalf("provenance union after sanitize = %+v; want sess-A + sess-B", recs[0].Provenance)
	}
}
package factsync

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// HTTPServer is the real Server adapter: it drives entire-api's fact-set sync
// endpoints (internal/httpapi/brain_facts.go) over HTTP so the sync runner can talk to
// the hosted head. It is the production implementor of the Server seam that Sync/Resolve
// are written against (the tests use an in-memory fake with identical semantics).
//
// Wire contract (must stay in lockstep with brain_facts.go):
//
//	GET  {BaseURL}/api/v1/repos/{repoID}/brain/facts?branch=… → 200
//	     {found, ref, version, data(base64)}   (pull-gated)
//	POST {BaseURL}/api/v1/repos/{repoID}/brain/facts/advance  → 200
//	     {newRef, version, changed}           (push-gated)
//	     body {branch, oldRef, old_ref, data(base64)}
//	     412/409 → the head advanced concurrently (→ ErrConflict, re-read + re-merge)
//	     changed=false or unchanged:true → the merge changed nothing (→ ErrNoChange, converged)
//	     changed omitted with newRef==oldRef preserves legacy no-op compatibility
//
// Data crosses the wire base64-encoded: huma serializes a Go []byte as a base64 JSON
// string, and encoding/json here does the same on both sides, so the []byte fields match
// byte-for-byte. Authorization is a bearer token (the member's session/runner token).
type HTTPServer struct {
	BaseURL string       // entire-api origin, e.g. https://api.entire.io (no trailing slash needed)
	Token   string       // bearer token; sent as Authorization: Bearer <token> when non-empty
	Client  *http.Client // defaults to http.DefaultClient when nil
}

func (h *HTTPServer) client() *http.Client {
	if h.Client != nil {
		return h.Client
	}
	return http.DefaultClient
}

func (h *HTTPServer) newRequest(ctx context.Context, method, path string, body io.Reader) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, method, strings.TrimRight(h.BaseURL, "/")+path, body)
	if err != nil {
		return nil, err
	}
	if h.Token != "" {
		req.Header.Set("Authorization", "Bearer "+h.Token)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return req, nil
}

// Current reads the branch's fact-set head. A 200 with found=false (no head yet) returns
// found=false and nil plaintext; the data field is base64-decoded by encoding/json into
// the []byte. Any non-200 is an error (the runner cannot merge against an unknown state).
func (h *HTTPServer) Current(ctx context.Context, repoID, branch string) (string, []byte, bool, error) {
	path := fmt.Sprintf("/api/v1/repos/%s/brain/facts?branch=%s", url.PathEscape(repoID), url.QueryEscape(branch))
	req, err := h.newRequest(ctx, http.MethodGet, path, nil)
	if err != nil {
		return "", nil, false, err
	}
	resp, err := h.client().Do(req)
	if err != nil {
		return "", nil, false, fmt.Errorf("factsync: GET fact-set head %s/%s: %w", repoID, branch, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", nil, false, fmt.Errorf("factsync: GET fact-set head %s/%s: unexpected status %s", repoID, branch, resp.Status)
	}
	var out struct {
		Found   bool   `json:"found"`
		Ref     string `json:"ref"`
		Version int64  `json:"version"`
		Data    []byte `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", nil, false, fmt.Errorf("factsync: decode fact-set head %s/%s: %w", repoID, branch, err)
	}
	if !out.Found {
		return "", nil, false, nil
	}
	return out.Ref, out.Data, true, nil
}

// Advance compare-and-swaps the head onto plaintext, mapping the endpoint's outcomes to
// the Server contract: 200 with changed → the new ref; 200 with changed=false
// or unchanged:true → ErrNoChange; 412/409 → ErrConflict. Any other status is
// an error (a 400 empty-data, 404 unknown repo, 503 unconfigured, or 5xx —
// none of which the runner should paper over). The duplicated ref spellings
// keep mixed-version entire-api / entire-brain rollouts compatible.
func (h *HTTPServer) Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (string, error) {
	reqBody := struct {
		Branch       string `json:"branch"`
		OldRef       string `json:"oldRef"`
		OldRefLegacy string `json:"old_ref"`
		Data         []byte `json:"data"`
	}{Branch: branch, OldRef: oldRef, OldRefLegacy: oldRef, Data: plaintext}
	buf, err := json.Marshal(reqBody)
	if err != nil {
		return "", err
	}
	path := fmt.Sprintf("/api/v1/repos/%s/brain/facts/advance", url.PathEscape(repoID))
	req, err := h.newRequest(ctx, http.MethodPost, path, bytes.NewReader(buf))
	if err != nil {
		return "", err
	}
	resp, err := h.client().Do(req)
	if err != nil {
		return "", fmt.Errorf("factsync: POST advance %s/%s: %w", repoID, branch, err)
	}
	defer resp.Body.Close()

	switch resp.StatusCode {
	case http.StatusOK:
		var out struct {
			NewRef          string `json:"newRef"`
			NewRefLegacy    string `json:"new_ref"`
			Version         int64  `json:"version"`
			Changed         *bool  `json:"changed"`
			UnchangedLegacy *bool  `json:"unchanged"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			return "", fmt.Errorf("factsync: decode advance %s/%s: %w", repoID, branch, err)
		}
		if out.Changed != nil && !*out.Changed {
			return "", ErrNoChange
		}
		if out.UnchangedLegacy != nil && *out.UnchangedLegacy {
			return "", ErrNoChange
		}
		newRef := out.NewRef
		if newRef == "" {
			newRef = out.NewRefLegacy
		}

