   110		// A brand-new backend over the SAME dir reads the persisted head back.
   111		b2, err := NewLocalBackend(dir, "gh/entireio/cli", testNow)
   112		if err != nil {
   113			t.Fatalf("reopen backend: %v", err)
   114		}
   115		reRef, reBlob, found, err := b2.Current(ctx, "repo", "main")
   116		if err != nil || !found || reRef != ref || !bytes.Equal(reBlob, plaintext) {
   117			t.Fatalf("reopened Current = (%q, found=%v, err=%v); want persisted (%q, %q)", reRef, found, err, ref, plaintext)
   118		}
