   211	// TestBackendTwoWriterInterleaveViaSync drives factsync.Sync against the real
   212	// local backend through a deterministic conflict: member M reads, competitor C
   213	// advances the head underneath, M's Advance conflicts, and Sync re-reads +
   214	// re-merges. The converged head must hold ALL THREE members' facts — nothing
   215	// dropped through the conflict/retry.
   216	func TestBackendTwoWriterInterleaveViaSync(t *testing.T) {
   217		ctx := context.Background()
   218		now := testNow()
   219		b, _ := newBackend(t)
   220	
   221		memberA := []factmerge.Record{fact("api timeouts default to 30s", []string{"api/config"}, "s-A")}
   222		if _, err := factsync.Sync(ctx, b, "repo", "main", "member-A", memberA, now); err != nil {
   223			t.Fatalf("prime head with member A: %v", err)
   224		}
   225	
   226		wrapped := &interposeOnce{
   227			inner:      b,
   228			competitor: []factmerge.Record{fact("migrations run on deploy", []string{"ops/deploy"}, "s-C")},
   229			now:        now,
   230			armed:      true,
   231		}
   232		memberM := []factmerge.Record{fact("the build uses bazel", []string{"build/tooling"}, "s-M")}
   233		res, err := factsync.Sync(ctx, wrapped, "repo", "main", "member-M", memberM, now)
   234		if err != nil {
   235			t.Fatalf("member M sync: %v", err)
   236		}
   237		if res.Attempts < 2 {
   238			t.Fatalf("expected a retry after the interposed conflict (Attempts>=2), got %d", res.Attempts)
   239		}
   240		if !res.Published {
   241			t.Fatalf("member M sync did not publish")
   242		}
   243	
   244		_, blob, found, err := b.Current(ctx, "repo", "main")
   245		if err != nil || !found {
   246			t.Fatalf("final Current: found=%v err=%v", found, err)
   247		}
   248		got := factTexts(t, blob)
   249		for _, want := range []string{"api timeouts default to 30s", "migrations run on deploy", "the build uses bazel"} {
   250			if !got[want] {
   251				t.Fatalf("converged head missing %q; got %v", want, got)
   252			}
   253		}
   254		if len(got) != 3 {
   255			t.Fatalf("converged head has %d distinct facts; want 3", len(got))
   256		}
   257	}
   258	
   259	// TestBackendConcurrentCreateNoLostUpdate is the regression for the create-path
   260	// race: two backends on the SAME on-disk repo (two processes) both create the
   261	// head from empty at once. go-git's create ref write is UNCONDITIONAL (it skips
   262	// the absence check when the old ref is nil), so before the advisory lock both
   263	// creates "won" and one member's facts were silently dropped. With the lock,
   264	// exactly one wins and the loser gets ErrConflict — Sync then re-reads and
   265	// re-merges, never dropping a member's facts.
   266	func TestBackendConcurrentCreateNoLostUpdate(t *testing.T) {
   267		dir := filepath.Join(t.TempDir(), "gitmeta.git")
   268		bA, err := NewLocalBackend(dir, "gh/entireio/cli", testNow)
   269		if err != nil {
   270			t.Fatalf("NewLocalBackend A: %v", err)
   271		}
   272		bB, err := NewLocalBackend(dir, "gh/entireio/cli", testNow)
   273		if err != nil {
   274			t.Fatalf("NewLocalBackend B: %v", err)
   275		}
   276	
   277		blobA := ndjson(t, fact("fact A", []string{"topic/a"}, "sA"))
   278		blobB := ndjson(t, fact("fact B", []string{"topic/b"}, "sB"))
   279	
   280		type res struct {
   281			ref string
   282			err error
   283		}
   284		ch := make(chan res, 2)
   285		var wg sync.WaitGroup
   286		wg.Add(2)
   287		go func() { defer wg.Done(); r, e := bA.Advance(context.Background(), "repo", "main", "", blobA); ch <- res{r, e} }()
   288		go func() { defer wg.Done(); r, e := bB.Advance(context.Background(), "repo", "main", "", blobB); ch <- res{r, e} }()
   289		wg.Wait()
   290		close(ch)
   291	
   292		wins, conflicts := 0, 0
   293		for r := range ch {
   294			switch {
   295			case r.err == nil && r.ref != "":
   296				wins++
   297			case errors.Is(r.err, factsync.ErrConflict):
   298				conflicts++
   299			default:
   300				t.Fatalf("unexpected Advance result: ref=%q err=%v", r.ref, r.err)
   301			}
   302		}
   303		if wins != 1 || conflicts != 1 {
   304			t.Fatalf("concurrent create: want exactly 1 win + 1 conflict, got wins=%d conflicts=%d", wins, conflicts)
   305		}
   306	
   307		// The head + blob left on disk are consistent — the racer did not corrupt it.
   308		ref, blob, found, err := bA.Current(context.Background(), "repo", "main")
   309		if err != nil {
   310			t.Fatalf("Current after race: %v", err)
   311		}
   312		if !found {
   313			t.Fatal("head missing after a successful create")
   314		}
   315		if FactSetRef(blob) != ref {
   316			t.Fatalf("blob/head mismatch after race: blob ref %s != head %s", FactSetRef(blob), ref)
   317		}
   318	}
