+		return "", "", "", err
+	}
+	generationsRoot := filepath.Join(env.BrainDir, generationsRel)
+	payload, err := json.Marshal(struct {
+		Report semanticTraceIngestReport `json:"report"`
+		Traces []semanticRuntimeTrace    `json:"traces"`
