package cli

import (
	"fmt"
	"reflect"
	"strings"
	"sync"
	"testing"
	"time"
)

func TestConcurrentFactCommitsAreLossless(t *testing.T) {
	brainDir := t.TempDir()
	branch := "main"
	now := time.Date(2026, 6, 8, 12, 0, 0, 0, time.UTC)
	const workers = 32
	makeFact := func(text string, paths []string, at time.Time) factRecord {
		p := normalizeFactPaths(paths)
		return factRecord{
			ID:        factRecordID(text, p),
			Paths:     p,
			Text:      text,
			Branch:    branch,
			Origin:    factOriginDistilled,
			Status:    factStatusActive,
			CreatedAt: at,
			UpdatedAt: at,
		}
	}

	start := make(chan struct{})
	errs := make(chan error, workers)
	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			unique := makeFact(fmt.Sprintf("unique fact %02d", i), []string{"project.tooling.stack"}, now.Add(time.Duration(i)*time.Second))
			unique.Provenance = []factAnchor{{SessionID: fmt.Sprintf("unique-%02d", i), Line: i + 1}}
			shared := makeFact("shared fact", []string{"preferences.coding.style"}, now)
			shared.Provenance = []factAnchor{{SessionID: fmt.Sprintf("shared-%02d", i), Line: i + 1}}
			errs <- withBrainWriteLock(brainDir, func() error {
				facts, err := loadFacts(brainDir, branch)
				if err != nil {
					return err
				}
				facts = upsertFact(facts, unique)
				facts = upsertFact(facts, shared)
				if err := writeFacts(brainDir, branch, facts); err != nil {
					return err
				}
				return updateFactSourceManifestLocked(brainDir, now)
			})
		}()
	}
	close(start)
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Fatalf("concurrent commit: %v", err)
		}
	}

	facts, err := loadFacts(brainDir, branch)
	if err != nil {
		t.Fatalf("load facts: %v", err)
	}
	if got, want := len(facts), workers+1; got != want {
		t.Fatalf("facts len = %d, want %d: %+v", got, want, facts)
	}
	ids := map[string]factRecord{}
	for _, fact := range facts {
		if _, exists := ids[fact.ID]; exists {
			t.Fatalf("duplicate fact id on disk: %s", fact.ID)
		}
		ids[fact.ID] = fact
	}
	sharedID := factRecordID("shared fact", normalizeFactPaths([]string{"preferences.coding.style"}))
	shared, ok := ids[sharedID]
	if !ok {
		t.Fatalf("shared fact missing")
	}
	if got := len(shared.Provenance); got != workers {
		t.Fatalf("shared provenance len = %d, want %d: %+v", got, workers, shared.Provenance)
	}
	for i := 0; i < workers; i++ {
		id := factRecordID(fmt.Sprintf("unique fact %02d", i), normalizeFactPaths([]string{"project.tooling.stack"}))
		if _, ok := ids[id]; !ok {
			t.Fatalf("unique fact %d missing", i)
		}
	}
	sorted := append([]factRecord(nil), facts...)
	sortFactRecords(sorted)
	if !reflect.DeepEqual(facts, sorted) {
		var idsOnDisk []string
		for _, fact := range facts {
			idsOnDisk = append(idsOnDisk, fact.ID)
		}
		t.Fatalf("facts are not deterministically sorted: %s", strings.Join(idsOnDisk, ", "))
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		t.Fatalf("load manifest: %v", err)
	}
	if manifest.Sources == nil || manifest.Sources.Facts == nil {
		t.Fatalf("facts source missing from manifest: %+v", manifest.Sources)
	}
	if manifest.Sources.Facts.Facts != workers+1 || manifest.Sources.Facts.Distilled != workers+1 {
		t.Fatalf("manifest fact counts wrong: %+v", manifest.Sources.Facts)
	}
}
	if len(w.writes) != 2 || w.writes[0] != "aaa" || w.writes[1] != "bbb" {
		t.Fatalf("writeText did not stream incrementally: %#v", w.writes)
	}
}

func TestVitalityMCPSurfacesRecordReceipts(t *testing.T) {
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
	now := time.Date(2026, 6, 9, 12, 0, 0, 0, time.UTC)
	opts := Options{Version: "test-version", Env: env, Runner: runner, Now: func() time.Time { return now }}
	storage, err := repoStoragePaths((&cobra.Command{}).Context(), runner, env, repoDir)
	if err != nil {
		t.Fatalf("storage: %v", err)
	}
	branch := "feature/mcp"
	fact := vitalityTestFact("qmd retrieval alpha contract", branch, now)
	if err := writeFacts(storage.BrainDir, branch, []factRecord{fact}); err != nil {
		t.Fatalf("write facts: %v", err)
	}

	input := frameMCP(fmt.Sprintf(`{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"brain_search","arguments":{"query":"qmd retrieval alpha","limit":1,"branch":%q}}}`, branch)) +
		frameMCP(fmt.Sprintf(`{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"brain_get","arguments":{"id":%q,"branch":%q}}}`, fact.ID, branch))
	var out bytes.Buffer
	if err := runMCP((&cobra.Command{}).Context(), strings.NewReader(input), &out, opts); err != nil {
		t.Fatalf("mcp: %v", err)
	}
	for i, response := range readMCPResponses(t, out.String()) {
		if response["error"] != nil {
			t.Fatalf("response %d returned error: %+v", i+1, response)
		}
	}

	rollup := vitalityViewOrFatal(t, storage.BrainDir, branch)
	entry := rollup.Facts[fact.ID]
	if entry == nil || entry.Served != 2 {
		t.Fatalf("mcp receipts = %+v", entry)
	}
	if entry.Surfaces["mcp:brain_search"] != 1 || entry.Surfaces["mcp:brain_get"] != 1 {
		t.Fatalf("mcp surfaces = %+v", entry.Surfaces)
	}
	if entry.LastHead != "aaa111" {
		t.Fatalf("mcp head = %q", entry.LastHead)
	}
	sidecar := string(vitalitySidecarBytes(t, storage.BrainDir, branch))
	if strings.Contains(sidecar, "qmd retrieval alpha\"") || strings.Contains(sidecar, `"task":"`) {
		t.Fatalf("raw query text persisted:\n%s", sidecar)
	}
}

func TestVitalityConcurrentAppendsAreLossless(t *testing.T) {
	brainDir := t.TempDir()
	branch := "main"
	now := time.Date(2026, 6, 8, 12, 0, 0, 0, time.UTC)
	const workers = 32

	start := make(chan struct{})
	errs := make(chan error, workers)
	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			events := []vitalityEvent{
				{Type: vitalityEventServed, FactID: "fact:shared", At: now.Add(time.Duration(i) * time.Second), Surface: "recall", Branch: branch},
				{Type: vitalityEventServed, FactID: fmt.Sprintf("fact:unique-%02d", i), At: now, Surface: "query", Branch: branch},
			}
			errs <- appendVitalityEventsBoundedWithLockTimeout(
				brainDir, branch, events, factsVitalityLogMaxBytes, time.Second,
			)
		}()
	}
	close(start)
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Fatalf("concurrent append: %v", err)
		}
	}

	rollup, stats, err := compactVitality(brainDir, branch)
	if err != nil {
		t.Fatalf("compact: %v", err)
	}
	if stats.Malformed != 0 {
		t.Fatalf("interleaved appends corrupted the log: %+v", stats)
	}
	if got := rollup.Facts["fact:shared"]; got == nil || got.Served != workers {
		t.Fatalf("shared fact receipts = %+v, want %d", got, workers)
	}
	total := 0
	for _, entry := range rollup.Facts {
		total += entry.Served
	}
	if total != workers*2 || len(rollup.Facts) != workers+1 {
		t.Fatalf("lost receipts: total=%d facts=%d", total, len(rollup.Facts))
